import type { Telemetry, TimerMetric } from '../types'

/**
 * This is a no-op telemetry implementation that does nothing.
 */
export class NoOpTelemetry implements Telemetry {
    startTimerEvent(): TimerMetric {
        return {
            end: () => ({ name: '', data: {} }),
        }
    }
    start = () => {}
    sendEvent = () => {}
    error = () => {}
}
